1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <link rel="icon" href="data:,">
11	
12	  <style>
13	    :root {
14	      --circle-hue: #8ec5ff;
15	      --circle-core: #4a7dd9;
16	      --circle-shadow: #1f3a75;
17	      --cycle: 2.5s;
18	    }
19	    * {
20	      margin: 0;
21	      padding: 0;
22	      box-sizing: border-box;
23	    }
24	    body {
25	      width: 100vw;
26	      height: 100vh;
27	      height: 100dvh;
28	      display: flex;
29	      flex-direction: column;
30	      justify-content: center;
31	      align-items: center;
32	      gap: 24px;
33	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
34	      overflow: hidden;
35	    }
36	    svg {
37	      width: min(400px, 80vmin);
38	      height: min(400px, 80vmin);
39	      overflow: visible;
40	      cursor: pointer;
41	      user-select: none;
42	      -webkit-tap-highlight-color: transparent;
43	      transition: filter 0.3s ease;
44	    }
45	    .circle-btn:hover svg {
46	      filter: brightness(1.08);
47	    }
48	    .ambient {
49	      fill: var(--circle-hue);
50	      opacity: 0.12;
51	      filter: blur(30px);
52	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
53	      transform-origin: 200px 200px;
54	      will-change: transform, opacity;
55	    }
56	    .core {
57	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
58	      transform-origin: 200px 200px;
59	      filter: url(#glow);
60	      will-change: transform, opacity;
61	    }
62	    .highlight {
63	      fill: url(#highlightGradient);
64	      transform-origin: 200px 200px;
65	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
66	      pointer-events: none;
67	      will-change: transform, opacity;
68	    }
69	    .ring {
70	      fill: none;
71	      stroke: var(--circle-hue);
72	      stroke-width: 2.5;
73	      transform-origin: 200px 200px;
74	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
75	      will-change: transform, opacity, stroke-width;
76	    }
77	    .ring--delay-1 {
78	      animation-delay: calc(var(--cycle) / 3);
79	    }
80	    .ring--delay-2 {
81	      animation-delay: calc(var(--cycle) / 3 * 2);
82	    }
83	    @keyframes pulse {
84	      0%, 100% {
85	        transform: scale(1);
86	        opacity: 0.9;
87	      }
88	      50% {
89	        transform: scale(1.05);
90	        opacity: 1;
91	      }
92	    }
93	    @keyframes breathe {
94	      0%, 100% {
95	        transform: scale(0.95);
96	        opacity: 0.1;
97	      }
98	      50% {
99	        transform: scale(1.1);
100	        opacity: 0.18;
101	      }
102	    }
103	    @keyframes ripple {
104	      0% {
105	        transform: scale(1);
106	        opacity: 0.6;
107	        stroke-width: var(--ring-width, 2.5);
108	      }
109	      100% {
110	        transform: scale(1.35);
111	        opacity: 0;
112	        stroke-width: calc(var(--ring-width, 2.5) / 5);
113	      }
114	    }
115	    body.paused .core,
116	    body.paused .ring,
117	    body.paused .ambient,
118	    body.paused .highlight {
119	      animation-play-state: paused;
120	    }
121	    /* Force-paused until JS takes over (below), avoiding a flash of motion;
122	       once JS is ready, control defers entirely to body.paused so the user
123	       can still explicitly resume even with reduced motion preferred. */
124	    @media (prefers-reduced-motion: reduce) {
125	      body:not(.js-ready) .core,
126	      body:not(.js-ready) .ring,
127	      body:not(.js-ready) .ambient,
128	      body:not(.js-ready) .highlight {
129	        animation-play-state: paused;
130	      }
131	    }
132	    .speed-label {
133	      color: var(--circle-hue);
134	      font-family: system-ui, sans-serif;
135	      font-size: 0.85rem;
136	      letter-spacing: 0.05em;
137	      opacity: 0.85;
138	      user-select: none;
139	      text-align: center;
140	    }
141	    .hint {
142	      display: block;
143	      margin-top: 4px;
144	      font-size: 0.7rem;
145	      opacity: 1;
146	    }
147	    .controls {
148	      display: flex;
149	      align-items: center;
150	      gap: 12px;
151	      max-width: min(320px, 90vw);
152	    }
153	    .pause-btn {
154	      display: inline-flex;
155	      align-items: center;
156	      justify-content: center;
157	      width: 44px;
158	      height: 44px;
159	      padding: 0;
160	      border-radius: 50%;
161	      border: 1px solid var(--circle-hue);
162	      background: transparent;
163	      color: var(--circle-hue);
164	      cursor: pointer;
165	      touch-action: manipulation;
166	      transition: background 0.2s ease;
167	    }
168	    .pause-btn:hover {
169	      background: rgba(142, 197, 255, 0.15);
170	    }
171	    .pause-btn:focus-visible {
172	      outline: 2px solid var(--circle-hue);
173	      outline-offset: 2px;
174	    }
175	    @media (prefers-contrast: more) {
176	      .pause-btn {
177	        border-width: 2px;
178	      }
179	      .ring {
180	        --ring-width: 3.5;
181	      }
182	    }
183	    .pause-btn svg {
184	      width: 14px;
185	      height: 14px;
186	    }
187	    .circle-btn {
188	      display: inline-flex;
189	      padding: 0;
190	      border: none;
191	      background: none;
192	      cursor: pointer;
193	      touch-action: manipulation;
194	      -webkit-tap-highlight-color: transparent;
195	      border-radius: 50%;
196	    }
197	    .circle-btn:focus-visible {
198	      outline: none;
199	    }
200	    .circle-btn:focus-visible svg {
201	      outline: 2px solid var(--circle-hue);
202	      outline-offset: 8px;
203	      border-radius: 50%;
204	    }
205	    .no-js .controls {
206	      display: none;
207	    }
208	    .no-js .circle-btn {
209	      cursor: default;
210	    }
211	    .visually-hidden {
212	      position: absolute;
213	      width: 1px;
214	      height: 1px;
215	      padding: 0;
216	      margin: -1px;
217	      overflow: hidden;
218	      clip: rect(0, 0, 0, 0);
219	      white-space: nowrap;
220	      border: 0;
221	    }
222	    .noscript-note {
223	      color: var(--circle-hue);
224	      font-family: system-ui, sans-serif;
225	      font-size: 0.8rem;
226	      opacity: 0.75;
227	      text-align: center;
228	      max-width: min(320px, 90vw);
229	    }
230	  </style>
231	</head>
232	<body class="no-js">
233	  <h1 class="visually-hidden">Pulsing Circle</h1>
234	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation" aria-describedby="speedText speedHint" title="Pulsing blue circle animation">
235	  <svg viewBox="0 0 400 400" focusable="false" aria-hidden="true">
236	    <defs>
237	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
238	        <stop offset="0%" style="stop-color: var(--circle-hue)"/>
239	        <stop offset="55%" style="stop-color: var(--circle-core)"/>
240	        <stop offset="100%" style="stop-color: var(--circle-shadow)"/>
241	      </radialGradient>
242	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
243	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
244	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
245	      </radialGradient>
246	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
247	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
248	        <feColorMatrix in="blur" type="matrix"
249	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
250	        <feMerge>
251	          <feMergeNode in="tintedBlur"/>
252	          <feMergeNode in="SourceGraphic"/>
253	        </feMerge>
254	      </filter>
255	    </defs>
256	    <circle class="ambient" cx="200" cy="200" r="160"/>
257	    <circle class="ring" cx="200" cy="200" r="140"/>
258	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
259	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
260	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
261	    <circle class="highlight" cx="200" cy="200" r="140"/>
262	  </svg>
263	  </button>
264	  <div class="controls" role="group" aria-label="Animation controls">
265	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
266	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
267	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
268	      </svg>
269	    </button>
270	    <p class="speed-label" id="speedLabel">
271	      <span id="speedText" aria-live="polite">Normal speed</span>
272	      <span class="hint" id="speedHint">Activate or use arrow keys to change speed (Home/End for slowest/fastest)</span>
273	    </p>
274	  </div>
275	  <noscript>
276	    <p class="noscript-note">Enable JavaScript to change the animation speed or pause it.</p>
277	  </noscript>
278	  <script>
279	    const circleBtn = document.getElementById('circleBtn');
280	    const speedText = document.getElementById('speedText');
281	    const pauseBtn = document.getElementById('pauseBtn');
282	    const pauseIcon = document.getElementById('pauseIcon');
283	    const animatedEls = document.querySelectorAll('.core, .ring, .ambient, .highlight');
284	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
285	    const PAUSE_ICON = pauseIcon.innerHTML;
286	    const speeds = [
287	      { value: '2.5s', name: 'Normal speed' },
288	      { value: '1.2s', name: 'Fast speed' },
289	      { value: '4.5s', name: 'Slow speed' },
290	    ];
291	    const reducedMotionQuery = window.matchMedia
292	      ? window.matchMedia('(prefers-reduced-motion: reduce)')
293	      : { matches: false, addEventListener: null, addListener: null };
294	    let speedIndex = 0;
295	    let manuallyPaused = reducedMotionQuery.matches;
296	    // Once the user has explicitly toggled pause/play, respect that choice
297	    // instead of letting a later OS-level reduced-motion change override it.
298	    let userHasChosen = false;
299	
300	    const STORAGE_KEY = 'pulsing-circle-prefs';
301	    try {
302	      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
303	      if (saved && Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex]) {
304	        speedIndex = saved.speedIndex;
305	        circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
306	      }
307	      if (saved && typeof saved.manuallyPaused === 'boolean') {
308	        manuallyPaused = saved.manuallyPaused;
309	        userHasChosen = true;
310	      }
311	    } catch {
312	      // Ignore malformed or inaccessible storage; fall back to defaults.
313	    }
314	
315	    function savePrefs() {
316	      try {
317	        localStorage.setItem(STORAGE_KEY, JSON.stringify({ speedIndex, manuallyPaused }));
318	      } catch {
319	        // Storage may be unavailable (e.g. private browsing); ignore.
320	      }
321	    }
322	
323	    function updateLabels() {
324	      const { name } = speeds[speedIndex];
325	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
326	      circleBtn.title = `Activate to change pulse speed (currently ${name})`;
327	    }
328	
329	    function setSpeed(index) {
330	      speedIndex = index;
331	      circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
332	      restartAnimations();
333	      updateLabels();
334	      savePrefs();
335	    }
336	
337	    function cycleSpeed(direction = 1) {
338	      setSpeed((speedIndex + direction + speeds.length) % speeds.length);
339	    }
340	
341	    // Restart animations from the beginning so a new speed feels immediate
342	    // instead of jumping mid-cycle.
343	    function restartAnimations() {
344	      animatedEls.forEach((el) => {
345	        el.style.animation = 'none';
346	        void el.offsetWidth;
347	        el.style.animation = '';
348	      });
349	    }
350	
351	    function applyPauseState() {
352	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
353	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
354	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
355	      pauseBtn.setAttribute('title', manuallyPaused ? 'Resume animation' : 'Pause animation');
356	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
357	      updateLabels();
358	    }
359	
360	    function togglePause() {
361	      manuallyPaused = !manuallyPaused;
362	      userHasChosen = true;
363	      applyPauseState();
364	      savePrefs();
365	    }
366	
367	    circleBtn.addEventListener('click', () => cycleSpeed(1));
368	    circleBtn.addEventListener('keydown', (e) => {
369	      if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
370	        e.preventDefault();
371	        cycleSpeed(-1);
372	      } else if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
373	        e.preventDefault();
374	        cycleSpeed(1);
375	      } else if (e.key === 'Home') {
376	        e.preventDefault();
377	        setSpeed(2);
378	      } else if (e.key === 'End') {
379	        e.preventDefault();
380	        setSpeed(1);
381	      }
382	    });
383	    pauseBtn.addEventListener('click', togglePause);
384	
385	    document.addEventListener('visibilitychange', applyPauseState);
386	
387	    const onReducedMotionChange = (e) => {
388	      if (userHasChosen) return;
389	      manuallyPaused = e.matches;
390	      applyPauseState();
391	    };
392	    if (reducedMotionQuery.addEventListener) {
393	      reducedMotionQuery.addEventListener('change', onReducedMotionChange);
394	    } else if (reducedMotionQuery.addListener) {
395	      // Safari < 14 fallback.
396	      reducedMotionQuery.addListener(onReducedMotionChange);
397	    }
398	
399	    // Keep multiple open tabs/windows of this page in sync with each other.
400	    window.addEventListener('storage', (e) => {
401	      if (e.key !== STORAGE_KEY || !e.newValue) return;
402	      try {
403	        const saved = JSON.parse(e.newValue);
404	        if (Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex] && saved.speedIndex !== speedIndex) {
405	          speedIndex = saved.speedIndex;
406	          circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
407	          restartAnimations();
408	        }
409	        if (typeof saved.manuallyPaused === 'boolean') {
410	          manuallyPaused = saved.manuallyPaused;
411	          userHasChosen = true;
412	        }
413	        applyPauseState();
414	        updateLabels();
415	      } catch {
416	        // Ignore malformed storage updates from other tabs.
417	      }
418	    });
419	
420	    applyPauseState();
421	    updateLabels();
422	    circleBtn.setAttribute('aria-label', 'Pulsing blue circle animation. Activate to change pulse speed.');
423	    document.body.classList.add('js-ready');
424	    document.body.classList.remove('no-js');
425	  </script>
426	</body>
427	</html>
